-- Evidencia abierta aplicada al universo Fintech el 2026-09-09.
-- Script idempotente de datos; las métricas de catálogo y funciones de ranking viven en supabase/migrations.

select e.fintech_id,'MANUAL_VERTICAL_CORRECTION_REITY_2026_09_09',e.business_model,e.business_model_confidence,e.target_customer,e.target_customer_confidence,e.revenue_model,e.revenue_model_confidence,1,now(),
       jsonb_build_object('old_primary_vertical',e.primary_vertical,'new_primary_vertical','Crowdfunding','source_url','https://reity.cl/','basis','La web oficial define Reity como plataforma de crowdfunding para invertir en instrumentos de financiamiento respaldados por activos inmobiliarios tokenizados.','manual_validation',true)
from public.aml_fintech_entity e where e.fintech_id='ENT-RUT-77608001-2'
and not exists(select 1 from public.aml_fintech_profile_audit a where a.fintech_id=e.fintech_id and a.classifier_version='MANUAL_VERTICAL_CORRECTION_REITY_2026_09_09');

update public.aml_fintech_entity
set primary_vertical='Crowdfunding',profile_classifier_version='MANUAL_VERTICAL_CORRECTION_REITY_2026_09_09',profile_refreshed_at=now(),refreshed_at=now()
where fintech_id='ENT-RUT-77608001-2';

values('OFFICIAL|REITY|FIN_CROWDFUNDING|2026-09-09','ENTITY','ENT-RUT-77608001-2','FIN_CROWDFUNDING','OBSERVED','OFFICIAL_OPEN',1.0,'Reity se define como plataforma de crowdfunding para invertir en instrumentos de financiamiento con activos inmobiliarios y acciones de inmobiliarias como subyacente.','COMPANY_OFFICIAL','https://reity.cl/','Plataforma de crowdfunding con activos inmobiliarios tokenizados.',now(),now(),now())
on conflict(observation_key) do update set evidence_status=excluded.evidence_status,evidence_class=excluded.evidence_class,confidence=excluded.confidence,basis=excluded.basis,source_code=excluded.source_code,source_url=excluded.source_url,evidence_excerpt=excluded.evidence_excerpt,last_seen_at=now(),observed_at=excluded.observed_at;

on conflict(observation_key) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,unit=excluded.unit,qualifier=excluded.qualifier,geography=excluded.geography,evidence_type=excluded.evidence_type,confidence=excluded.confidence,source_code=excluded.source_code,source_url=excluded.source_url,observed_at=excluded.observed_at,basis=excluded.basis,metadata=excluded.metadata,last_seen_at=now();

select atlas_private.aml_fintech_refresh_market_weight();
